fun leastInterval(tasks: CharArray, n: Int): Int {
    val counts = tasks.toList().groupingBy { it }.eachCount().values
    val max = counts.max()
    val maxCount = counts.count { it == max }
    val frame = (max - 1) * (n + 1) + maxCount
    return maxOf(frame, tasks.size)
}

