fun knapsack(weights: IntArray, values: IntArray, capacity: Int): Int {
    val dp = IntArray(capacity + 1)
    for (i in weights.indices) {
        for (c in capacity downTo weights[i]) {
            dp[c] = maxOf(dp[c], dp[c - weights[i]] + values[i])
        }
    }
    return dp[capacity]
}

