fun uniquePaths(m: Int, n: Int): Int {
    val dp = Array(m) { IntArray(n) }
    for (r in 0 until m) dp[r][0] = 1
    for (c in 0 until n) dp[0][c] = 1
    for (r in 1 until m) for (c in 1 until n) {
        dp[r][c] = dp[r - 1][c] + dp[r][c - 1]
    }
    return dp[m - 1][n - 1]
}

