fun longestPalindrome(s: String): String {
    var start = 0
    var maxLen = 1
    fun expand(lo: Int, hi: Int): Int {
        var l = lo; var r = hi
        while (l >= 0 && r < s.length && s[l] == s[r]) { l--; r++ }
        return r - l - 1   // length of the palindrome found
    }
    for (i in s.indices) {
        val lenOdd = expand(i, i)
        val lenEven = expand(i, i + 1)
        val len = maxOf(lenOdd, lenEven)
        if (len > maxLen) {
            maxLen = len
            start = i - (len - 1) / 2
        }
    }
    return s.substring(start, start + maxLen)
}

