class TokenBucket(
    private val capacity: Long,
    private val refillPerSecond: Long,
) {
    private val state = HashMap<String, Bucket>()
    private class Bucket(var tokens: Long, var lastRefill: Long)

    fun allow(key: String, nowMs: Long): Boolean {
        val b = state.getOrPut(key) { Bucket(capacity, nowMs) }
        val elapsed = (nowMs - b.lastRefill) / 1000.0
        b.tokens = minOf(capacity, b.tokens + (elapsed * refillPerSecond).toLong())
        b.lastRefill = nowMs
        return if (b.tokens >= 1) { b.tokens--; true } else false
    }
}

